  $d = [self:mkdir]{path:f"~workspace/outputs/IT74_tree/강의자료_정리/${$wk}"}
  $c = [self:copy]{src:$it.path, dest:f"${$d.path}/${$it.name}"}
  return {week:$wk, file:$it.name}
}
return $done

#!ibl edition=2
$c = [self:copy]{src:"~workspace/outputs/IT74_tree/Downloads/file with spaces & (special).txt", dest:"~workspace/outputs/IT74_backup/백업 폴더 (9월)/메모 & 목록.txt"}
return [self:read]{path:"~workspace/outputs/IT74_backup/백업 폴더 (9월)/메모 & 목록.txt"}.text

#!ibl edition=2
$old = [self:list]{path:"~workspace/outputs/IT74_tree/Downloads"} >> [table:filter]{where:($r)=> !$r.is_dir && contains($r.name, ".dmg") && $r.mtime < "2026-08-28"}
$gone = $old >> [table:each]{ $x = [self:delete]{path:$it.path}
 return $it.name }
$left = [self:list]{path:"~workspace/outputs/IT74_tree/Downloads", pattern:"*.dmg"}
return {deleted:$gone, left:len($left)}

