$f = [self:list]{path:"~workspace/outputs/IT74_tree/프로젝트A"} >> [table:sort]{by:"name"}
$lines = $f >> [table:each]{ f"- ${$it.name}" }
$w = [self:write]{path:"~workspace/outputs/IT74_tree/프로젝트A/INDEX.md", content:"# 프로젝트A\n" + join("\n", $lines)}
return [self:read]{path:"~workspace/outputs/IT74_tree/프로젝트A/INDEX.md"}.text
